INSERT INTO materials (id, grade_id, topic_slug, type, library, slug, position, status, is_teaser, created_at, updated_at) VALUES ('2c567ada-2b47-456b-a4c9-1ad6dcb11495','9','solurile-terrei','foto','student','solurile-terrei-galerie-foto',13,'published',1,1783900000000,1783900000000);
INSERT INTO material_translations (material_id, locale, title, description, body) VALUES ('2c567ada-2b47-456b-a4c9-1ad6dcb11495','ro','Solurile Terrei (pedosfera) – galerie foto','Galerie foto pentru lecția Solurile Terrei: orizonturile solului, factorii pedogenetici, procesele de podzolire, calcifiere și lateritizare, textura și structura solului, tipurile zonale de sol.','{"captions":["Orizonturile solului (profil O–A–E–B–C–D și orizontul gleic)","Factorii de formare a solului (climă, rocă maternă, relief, vegetație, apă freatică, timp, om)","Podzolire – profil de alfisol/argiluvisol sub pădure de foioase și spodosol sub pădure de conifere","Calcifiere – profil de aridisol/calcisol de deșert și molisol de stepă","Lateritizare – profil de oxisol/feralsol sub pădure ecuatorială și ultisol de savană","Solul ca ecosistem – pedosfera, la întâlnirea atmosferei, biosferei, hidrosferei și litosferei, cu viețuitoarele din sol","Componentele solului – nisip, praf, argilă, aer, apă și viețuitoare (bacterii, fungi, insecte, râme)","Compoziția volumetrică a solului – spațiu poros (aer, apă) și material solid (mineral, organic)","Mărimea relativă a fracțiunilor granulometrice – nisip, praf și argilă","Textura solului – nisipoasă, argiloasă și lutoasă","Structura solului – tipuri de agregate (grăunțoasă, lamelară, poliedrică, prismatică, columnară)","Tipuri zonale de sol – de tundră, podzolic, cenușiu de pădure și de cernoziom","Tipuri zonale de sol – brun de semipustiu, brun-cenușiu de pustiu, crasnoziom și solonceac"]}');
